DECLARE
  l_existing_dept        NUMBER;
  l_missing_dept         NUMBER;
  l_expected_existing    NUMBER;
  l_actual_existing      NUMBER;
  l_expected_missing     NUMBER;
  l_actual_missing       NUMBER;
  l_expected_null        NUMBER;
  l_actual_null          NUMBER;
  l_missing_count_check  NUMBER;
  l_failures             PLS_INTEGER := 0;

  PROCEDURE report(
    p_check_name VARCHAR2,
    p_expected   NUMBER,
    p_actual     NUMBER
  ) IS
  BEGIN
    IF p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_check_name ||
        ' expected=' || TO_CHAR(p_expected) ||
        ' actual=' || TO_CHAR(p_actual)
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_check_name ||
        ' expected=' || TO_CHAR(p_expected) ||
        ' actual=' || TO_CHAR(p_actual)
      );
      l_failures := l_failures + 1;
    END IF;
  END report;
BEGIN
  SAVEPOINT test_savepoint;

  -- Find one non-NULL department_id that matches at least one employee.
  SELECT MIN(department_id)
    INTO l_existing_dept
    FROM employees
   WHERE department_id IS NOT NULL;

  IF l_existing_dept IS NULL THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: existing department setup - no non-NULL department_id found in employees'
    );
    l_failures := l_failures + 1;
    l_actual_existing := NULL;
    l_expected_existing := NULL;
  ELSE
    SELECT COUNT(*)
      INTO l_expected_existing
      FROM employees
     WHERE department_id = l_existing_dept;

    l_actual_existing := HARNESS_APP.headcount(l_existing_dept);

    report(
      'existing department_id=' || TO_CHAR(l_existing_dept),
      l_expected_existing,
      l_actual_existing
    );
  END IF;

  -- Choose a value that cannot match a non-NULL department_id: one less than the
  -- minimum non-NULL department_id. Confirm that it matches no rows.
  IF l_existing_dept IS NULL THEN
    l_missing_dept := -1;
  ELSE
    l_missing_dept := l_existing_dept - 1;
  END IF;

  SELECT COUNT(*)
    INTO l_missing_count_check
    FROM employees
   WHERE department_id = l_missing_dept;

  IF l_missing_count_check <> 0 THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: missing department setup - department_id=' ||
      TO_CHAR(l_missing_dept) ||
      ' unexpectedly matched ' ||
      TO_CHAR(l_missing_count_check) ||
      ' row(s)'
    );
    l_failures := l_failures + 1;
    l_expected_missing := NULL;
    l_actual_missing := NULL;
  ELSE
    SELECT COUNT(*)
      INTO l_expected_missing
      FROM employees
     WHERE department_id = l_missing_dept;

    l_actual_missing := HARNESS_APP.headcount(l_missing_dept);

    report(
      'missing department_id=' || TO_CHAR(l_missing_dept),
      l_expected_missing,
      l_actual_missing
    );
  END IF;

  -- NULL argument: the function compares with =, so NULL should match no rows.
  SELECT COUNT(*)
    INTO l_expected_null
    FROM employees
   WHERE department_id = CAST(NULL AS NUMBER);

  l_actual_null := HARNESS_APP.headcount(NULL);

  report(
    'NULL department_id',
    l_expected_null,
    l_actual_null
  );

  IF l_failures = 0 THEN
    DBMS_OUTPUT.PUT_LINE('PASS: all checks passed');
  ELSE
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: ' || TO_CHAR(l_failures) || ' check(s) failed'
    );
  END IF;

  ROLLBACK TO test_savepoint;

  IF l_failures <> 0 THEN
    RAISE_APPLICATION_ERROR(
      -20999,
      'headcount test block failed: ' || TO_CHAR(l_failures) || ' check(s) failed'
    );
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE(
      'UNEXPECTED ERROR: SQLCODE=' || TO_CHAR(SQLCODE) ||
      ' SQLERRM=' || SQLERRM
    );
    ROLLBACK TO test_savepoint;
    RAISE;
END;
/
```

This block calls the selected unit as `HARNESS_APP.headcount`; it does not copy the function body into the block.

Checks:

- Existing department: selects one non-NULL `department_id` from `employees`, computes the expected count with a separate `COUNT(*)` query, calls `HARNESS_APP.headcount` with that value, and compares the result.
- Missing department: chooses a `department_id` below the minimum non-NULL department value, confirms with `COUNT(*)` that it matches no rows, computes the expected count, calls `HARNESS_APP.headcount`, and compares the result.
- NULL argument: calls `HARNESS_APP.headcount(NULL)` and compares it with the expected no-match result produced by the same `=` comparison used by the function.
- Setup failures: if no non-NULL department row is found, or if the chosen missing department unexpectedly matches rows, the corresponding check prints `FAIL` with a reason and increments the failure counter.

